def check_commutativity(S, operation_results):
    non_commutative_pairs = []
    for i in range(len(S)):
        for j in range(len(S)):
            if i != j:
                a, b = S[i], S[j]
                if operation_results.get((a, b)) != operation_results.get((b, a)):
                    non_commutative_pairs.append((a, b))
    return non_commutative_pairs

# Example usage:
S = [1, 2, 3]
operation_results = {
    (1, 2): 3,
    (2, 1): 4,
    (1, 3): 4,
    (3, 1): 4,
    (2, 3): 5,
    (3, 2): 5
}

non_commutative_pairs = check_commutativity(S, operation_results)
print('Non-commutative pairs:', non_commutative_pairs)
